export const ERRORS=[20,-20,0,0,10,-10,0,0];
export const CONTEXTS={
 opportunity:{name:'Act on an opportunity',signal:'Opportunity index',direction:'high',act:'Act',wait:'Wait',need:'Worth acting on',missLabel:'Missed opportunity',falseLabel:'Unnecessary action',thresholdLabel:'Act at or above',description:'A higher value makes an opportunity worth acting on. Missing it is more costly than an unnecessary action in this example.',actual:[40,65,48,90,55,72,30,85],threshold:60,miss:8,falseAlarm:3},
 headroom:{name:'Investigate low headroom',signal:'Operating headroom index',direction:'low',act:'Investigate',wait:'Continue',need:'Investigation warranted',missLabel:'Missed investigation',falseLabel:'Unnecessary investigation',thresholdLabel:'Investigate at or below',description:'A lower headroom index warrants investigation. An optimistic error can hide the need to act; a pessimistic error can trigger unnecessary investigation.',actual:[70,42,62,30,55,46,85,35],threshold:45,miss:12,falseAlarm:2},
 capacity:{name:'Add review capacity',signal:'Review demand index',direction:'high',act:'Add capacity',wait:'Keep plan',need:'Extra capacity warranted',missLabel:'Missed capacity need',falseLabel:'Unnecessary capacity',thresholdLabel:'Add capacity at or above',description:'High demand warrants extra review capacity. In this example, reserving unnecessary capacity is more costly than missing a need.',actual:[45,72,63,90,55,69,35,85],threshold:70,miss:3,falseAlarm:10}
};
export function create(context='opportunity'){const p=CONTEXTS[context];if(!p)throw Error('Unknown decision context');return {context,actual:[...p.actual],order:[0,1,2,3,4,5,6,7],threshold:p.threshold,miss:p.miss,falseAlarm:p.falseAlarm};}
export function validate(s){if(!s||!Object.hasOwn(CONTEXTS,s.context??'opportunity')||!Array.isArray(s.actual)||s.actual.length!==8||s.actual.some(x=>!Number.isFinite(x)||x<20||x>100)||!Array.isArray(s.order)||s.order.length!==8||new Set(s.order).size!==8||s.order.some(x=>!Number.isInteger(x)||x<0||x>7)||!Number.isFinite(s.threshold)||s.threshold<20||s.threshold>100||![s.miss,s.falseAlarm].every(x=>Number.isFinite(x)&&x>=0&&x<=20))throw Error('Invalid decision experiment');return {context:s.context??'opportunity',actual:[...s.actual],order:[...s.order],threshold:s.threshold,miss:s.miss,falseAlarm:s.falseAlarm};}
export function setContext(s,id){const current=validate(s);return {...create(id),order:[...current.order]};}
export function isEdited(s){const preset=create(s.context);return ['threshold','miss','falseAlarm'].some(k=>s[k]!==preset[k])||s.actual.some((v,i)=>v!==preset.actual[i]);}
export function swap(s,from,to){const next=validate(s);if(![from,to].every(x=>Number.isInteger(x)&&x>=0&&x<8))throw Error('Unknown moment');[next.order[from],next.order[to]]=[next.order[to],next.order[from]];return next;}
export function evaluate(value){const s=validate(value),low=CONTEXTS[s.context].direction==='low';const rows=s.actual.map((actual,i)=>{const error=ERRORS[s.order[i]],forecast=actual+error,act=low?forecast<=s.threshold:forecast>=s.threshold,need=low?actual<=s.threshold:actual>=s.threshold,kind=need&&!act?'miss':act&&!need?'falseAlarm':'correct';return{actual,error,forecast,act,need,kind,cost:kind==='correct'?0:s[kind]};});return{rows,mae:rows.reduce((a,r)=>a+Math.abs(r.error),0)/8,rmse:Math.sqrt(rows.reduce((a,r)=>a+r.error*r.error,0)/8),loss:rows.reduce((a,r)=>a+r.cost,0),misses:rows.filter(r=>r.kind==='miss').length,falseAlarms:rows.filter(r=>r.kind==='falseAlarm').length,alwaysAct:rows.filter(r=>!r.need).length*s.falseAlarm,neverAct:rows.filter(r=>r.need).length*s.miss};}
export function compare(s,baseline){return baseline?evaluate({...validate(s),order:[...validate(baseline).order]}):null;}
